\label{T:2}
The number of octic fields with Galois closure as specified satisfies:
\begin{align*}
  \operatorname{\mathcal{N}}_8(S_4, X) &\ll X^{1/2}\,,\\
  \operatorname{\mathcal{N}}_8(\operatorname{GL}_2(\mathbb{F}_3),X)&\ll X^{3/5}\,,\\
  \operatorname{\mathcal{N}}_8(C_2^3\rtimes S_4, X)&\ll X^{9/14}\,,\\
  \operatorname{\mathcal{N}}_8(Q_8\rtimes S_4,X)&\ll X^{3/5}\,.
\end{align*}

We begin by writing
\begin{equation} \label{eq: full sum}
    \operatorname{\mathcal{N}}_{8}(\mathcal{G}, X)
    =
    \sum_{\substack{[K:\mathbb{Q}] = 4\\G(\widetilde{K}/\mathbb{Q}) \cong S_4\\|\Delta_K| \leq \sqrt{X}\\}}
    \sum_{\substack{[L:K]=2\\\operatorname{N}(\Delta_{L/K}) \leq X/\Delta_K^2\\}}1
    \,.
\end{equation}
By Theorem~2 of~\cite{MR4808549}, the inner sum equals
\begin{align}
\nonumber
\sum_{\substack{[L:K]=2\\\operatorname{N}(\Delta_{L/K}) \leq X/\Delta_K^2}}1
&=
\frac{X}{\Delta_K^2}\frac{1}{2^{r_2(K)}}\frac{\zeta_K^*(1)}{\zeta_K(2)} 
+
O \left( 
|\text{Cl}(K)[2]| \cdot |\Delta_K|^{1/5} \left(\frac{X}{\Delta_K^2}\right)^{3/5}
\log (X/\Delta_K^2)^{3}
\right)
\\
\label{E:AT1}
&=
\frac{X}{\Delta_K^2}\frac{1}{2^{r_2(K)}}\frac{\zeta_K^*(1)}{\zeta_K(2)} 
+
O \left( 
|\Delta_K|^{\kappa-1+\varepsilon} X^{3/5+\varepsilon}
\right)
\,.
\end{align}
Here we have used
Theorem~1.1 of~\cite{MR4155220}, which states that
\begin{equation}\label{E:torsion}
|\text{Cl}(K)[2]| \ll |\Delta_K|^{\kappa + \varepsilon}.
\end{equation}
Moreover, using the parametrization given in~\cite{MR1918290}, or alternatively
Equation 3 in Section 3.2 of~\cite{MR4808549},
we also have the weaker estimate
\begin{align}\label{E:AT2}
\sum_{\substack{[L:K]=2\\\operatorname{N}(\Delta_{L/K}) \leq X/\Delta_K^2}}1
&\leq
|S_2(K)|\sum_{\operatorname{N}(\mathfrak{a}) \leq X/\Delta_K^2}1

&\ll
\left|\operatorname{Cl}(K)[2]\right|\cdot|\Delta_K|^\varepsilon\left(\frac{X}{\Delta_K^2}\right)

&\ll
|\Delta_K|^{\kappa-2+\varepsilon}X
\,.
\end{align}
In the above, $S_2(K)$ is the $2$-Selmer group of $K$, which can
be bounded using Proposition 3.2 of~\cite{MR1918290}.  Moreover,
we have used $\sum_{\operatorname{N}(\mathfrak{a}) \leq Y}1\leq|\Delta_K|^\varepsilon Y$;
this is not hard to derive and appears as Equation~(21) in \cite{MR4808549}.

Let $0<Z<X^{1/2}$ be a parameter.  Splitting the sum in (\ref{eq: full sum}), we have
\begin{align}\label{E:split}
    \operatorname{\mathcal{N}}_{8}(\mathcal{G}, X)
    &=
    \sum_{
        \substack{
            [K:\mathbb{Q}] = 4\\
            G(\widetilde{K}/\mathbb{Q}) \cong S_4\\
            |\Delta_K| \leq Z\\
        }
    }
    \sum_{
    \substack{
    [L:K]=2\\
    \operatorname{N}(\Delta_{L/K}) \leq X/\Delta_K^2\\
    }
    }{1}
    +
        \sum_{
        \substack{
            [K:\mathbb{Q}] = 4\\
            G(\widetilde{K}/\mathbb{Q}) \cong S_4\\
            Z<|\Delta_K| \leq \sqrt{X}\\
        }
    }
    \sum_{
    \substack{
    [L:K]=2\\
    \operatorname{N}(\Delta_{L/K}) \leq X/\Delta_K^2\\
    }
    }{1}
    \,.
\end{align}
Using (\ref{E:AT1}), the first piece of (\ref{E:split}) equals
\begin{align}
\nonumber
    X
   \sum_{
        \substack{
            [K:\mathbb{Q}] = 4\\
            G(\widetilde{K}/\mathbb{Q}) \cong S_4\\
            |\Delta_K| \leq Z\\
        }
    }
    \frac{1}{2^{r_2(K)}\Delta_K^2}\cdot\frac{\zeta_K^*(1)}{\zeta_K(2)} 
    +
        O
    \left(
    X^{3/5+\varepsilon}
    \sum_{
        \substack{
            [K:\mathbb{Q}] = 4\\
            G(\widetilde{K}/\mathbb{Q}) \cong S_4\\
            |\Delta_K| \leq Z\\
        }
    }
    |\Delta_K|^{\kappa-1+\varepsilon}
    \right)
    \,.
\end{align}





























From~\cite{MR2183288} one knows $\operatorname{\mathcal{N}}_4(S_4,X)\ll X$, and therefore partial summation yields
\begin{align}
\sum_{\substack{[K:\mathbb{Q}] = 4\\G(\widetilde{K}/\mathbb{Q}) \cong S_4\\|\Delta_K| > Z\\ }}
\frac{1}{2^{r_2(K)}\Delta_K^2}\cdot\frac{\zeta_K^*(1)}{\zeta_K(2)} 
\ll
\frac{1}{Z^{1-\varepsilon}}
\,,\qquad
\sum_{\substack{[K:\mathbb{Q}] = 4\\G(\widetilde{K}/\mathbb{Q}) \cong S_4\\|\Delta_K| \leq Z\\}}|\Delta_K|^{\kappa-1+\varepsilon}
\ll
Z^{\kappa+\varepsilon}\,.
\end{align}
Note we have also used the estimate $\zeta^*_K(1)\ll |\Delta_K|^\varepsilon$.
Therefore we have
$$
    \sum_{
        \substack{
            [K:\mathbb{Q}] = 4\\
            G(\widetilde{K}/\mathbb{Q}) \cong S_4\\
            |\Delta_K| \leq Z\\
        }
    }
    \sum_{
    \substack{
    [L:K]=2\\
    \operatorname{N}(\Delta_{L/K}) \leq X/\Delta_K^2\\
    }
    }{1}
    =CX+O\left(XZ^{-1+\varepsilon}\right)+O\left(X^{3/5+\varepsilon}Z^{\kappa+\varepsilon}\right)
    \,.
$$
For the second piece of (\ref{E:split}), we use (\ref{E:AT2}) to obtain
$$
        \sum_{
        \substack{
            [K:\mathbb{Q}] = 4\\
            G(\widetilde{K}/\mathbb{Q}) \cong S_4\\
            Z<|\Delta_K| \leq \sqrt{X}\\
        }
    }
    \sum_{
    \substack{
    [L:K]=2\\
    \operatorname{N}(\Delta_{L/K}) \leq X/\Delta_K^2\\
    }
    }{1}
  \ll
  X
          \sum_{
        \substack{
            [K:\mathbb{Q}] = 4\\
            G(\widetilde{K}/\mathbb{Q}) \cong S_4\\
            Z<|\Delta_K| \leq \sqrt{X}\\
        }
    }
    |\Delta_K|^{\kappa-2+\varepsilon}
\ll
XZ^{\kappa-1+\varepsilon}
\,.
$$
Summarizing, the error term is
$$
O\left(XZ^{-1+\varepsilon}\right)+O\left(X^{3/5+\varepsilon}Z^{\kappa+\varepsilon}\right)
+O\left(
XZ^{\kappa-1+\varepsilon}
\right)
\,.
$$
Choosing $Z=X^{2/5}$, we have

\begin{equation}\label{E:big.count}
\operatorname{\mathcal{N}}_8(\mathcal{G}, X) = C X + O(X^{3/5 + 2\kappa/5 + \varepsilon}),
\end{equation}
where $C$ is as in Theorem~\ref{T:1}.

Given an $S_4$-octic field $L$, we know that $L$ contains a unique $S_4$-quartic field $K$.
Moreover, $L$ is the unique $S_4$-octic field satisfying $K\subseteq L\subseteq\widetilde{K}$.

Therefore, given an $S_4$-quartic field $K$, we can define
$$
  f_K(X) \colonequals \begin{cases}
  1, & \operatorname{N}(\Delta_{L/K})\le X/\Delta_K^2,\\
  0 & \text{otherwise},
  \end{cases}
$$
where $L$ is the unique $S_4$-octic containing $K$.
We then have
\begin{align*}
    \operatorname{\mathcal{N}}_8(S_4,X) = \sum_{\substack{[K:\mathbb{Q}]=4 \\ G(\widetilde{K}/\mathbb{Q}) \cong S_4 \\ |\Delta_K|\le \sqrt{X}}}f_K(X).
\end{align*}






Trivially bounding this sum and using $\operatorname{\mathcal{N}}_4(S_4,X)\ll X$ (see~\cite{MR2183288}) yields 
\begin{align*}
    \operatorname{\mathcal{N}}_8(S_4,X) \ll X^{1/2},
\end{align*}
as desired.

\label{lemma: splitting in G}
  Let $L/K/\mathbb{Q}$ be as above. Let $p$ be a prime that is tamely ramified in $\widetilde{L}$.
    \begin{enumerate}
        \item We have $e(\widetilde{L}/ p) \in \{2,3,4,6,8\}$.
        \item Suppose $e(\widetilde{L}/p) = 2$.  If the ramification indices $e(\mathfrak{p}/p)$
        for $\mathfrak{p}$ in $K$ over $p$ are not all the same,
        then we must have $f(\widetilde{L}/p) \leq 2$.
        \item
        Suppose $e(\mathfrak{P}/p)\leq 2$ for all primes $\mathfrak{P}$ in $L$ above $p$.
        If the indices $e(\mathfrak{p}/p)$ for $\mathfrak{p}$ in $K$ over $p$ are not all equal,
        then we must have $e(\widetilde{L}/p) = 2$ and $f(\widetilde{L}/p) \leq 2$.
    \end{enumerate}

In~\cite{BCT}, the analogous result for $S_5$-quintic fields is proved.  We mimic the same proof,
but use the parametrization for quartic fields given in~\cite{MR2183288}.

For a $G_{\mathbb{Z}}$-invariant set $S \subseteq V_{\mathbb{Z}}$, let $\operatorname{\mathcal{N}}(S,X)$ denote the number of absolutely irreducible $G_{\mathbb{Z}}$-orbits of $S$ having discriminant bounded by $X$. For a suitable box $H$ (which we determine later), with characteristic function $\Phi = \Phi_H$, we can sum through the three nondegenerate orbits of $G_{\mathbb{R}}$ on $V_{\mathbb{R}}$ to obtain
\begin{equation}\label{E:S4-tail-def}
\operatorname{\mathcal{N}}(S, X) = 
\sum_{i=0}^2
\frac{
\int_{v \in V_{\mathbb{R}}^{(i)}}
{\Phi(v)\#\{x \in \mathcal{F}v \cap S \text{ abs.~irr.} :   0 < |\operatorname{Disc}(x)| < X\} |\operatorname{Disc}(v)|^{-1} dv}
}{
M_i
},
\end{equation}
where $M_i = M_i(H)$ is a constant depending only on $i$ and $H$. Even if $S \subseteq V_{\mathbb{Z}}$ is not invariant under the action of $G_{\mathbb{Z}}$, we define $\operatorname{\mathcal{N}}(S,X)$ to be the quantity in Equation~\eqref{E:S4-tail-def}.
Following Lemma 7 of \cite{BCT}, we fix any of the 12 coordinates of $V_{\mathbb{Z}}$ as $y$ and let $\mathcal{Y} \subseteq \mathbb{A}_{\mathbb{Z}}^{12}$ be defined by
\[
\mathcal{Y} \colonequals \left\{v \colon \operatorname{Disc}(v) = \frac{\partial \operatorname{Disc}}{\partial y}(v) = 0 \right\}\,,
\]
which is a subscheme of $\mathbb{A}_{\mathbb{Z}}^{12}$ of codimension 2. 

We know by the discussion in Section~4.2 of \cite{bhargava2014geometricsievedensitysquarefree} that for $v \in V_{\mathbb{Z}}$ absolutely irreducible, if $p^2 \mid \operatorname{Disc}(v)$ then $\operatorname{Disc}$ is strongly a multiple of $p^2$ at $v$. Moreover, by Lemma 3.6 of \cite{bhargava2014geometricsievedensitysquarefree}, we know that this implies $v \allowbreak\mkern5mu({\operator@font mod}\,\,p) \in \mathcal{Y}(\mathbb{F}_p)$. Thus, it suffices for our purposes to bound the quantity $\operatorname{\mathcal{N}}(S_Z(\mathcal{Y}), X)$, where we define $S_Z(\mathcal{Y})$ to be the intersection of the set
\[
\{v \in G_{\mathbb{Z}} \backslash V_{\mathbb{Z}} \colon \operatorname{Disc}(v) \neq 0 \text{ and } v \allowbreak\mkern5mu({\operator@font mod}\,\,q) \in \mathcal{Y}(\mathbb{Z}/q \mathbb{Z}) \text{ for some squarefree $q > Z$}\}
\]
with the set of all absolutely irreducible elements of $ V_{\mathbb{Z}}$.
By Lemma 11 of \cite{MR2183288}, the contribution from $v = (A,B)$ with $a_{11} = 0$ is $O(X^{11/12})$, so
\[
\operatorname{\mathcal{N}}(S_Z(\mathcal{Y}),X) 
\ll
\operatorname{\mathcal{N}}(S_Z(\mathcal{Y}) \cap \{a_{11} \neq 0\}, X) + O(X^{11/12}).
\]
Then we have by Equation 7 of \cite{MR2183288} that
\begin{equation}\label{S4-tail-eq1}
\begin{split}
\operatorname{\mathcal{N}}(S_Z(\mathcal{Y}) \cap \{a_{11} \neq 0\}, X) \\
    \ll
\int_{g \in K N'A'^{-1} \Lambda} &
\sum_{\substack{
        x \in S_Z(\mathcal{Y})\\
        a_{11} \neq 0\\
        |\operatorname{Disc}(x)| < X}}
\Phi(kna^{-1} \lambda x) s_1^{-2}s_2^{-6}s_3^{-6}\, 
d^{\times}\lambda\, d^{\times}s\, dn\, dk.
\end{split}
\end{equation}
Now let
\[
H \colonequals \{(A,B) \in V_{\mathbb{R}} \colon |a_{ij}|,|b_{ij}| \leq 10 \text{ and $\operatorname{Disc}$}(A,B) \geq 1\}.
\]
Then the compact set
\[
H' \colonequals \{(A,B) \in V_{\mathbb{R}} \colon |a_{ij}|,|b_{ij}| \leq 60 \text{ and $\operatorname{Disc}$}(A,B) \geq 1\}
\]
contains $KN'H$. Equation~\eqref{S4-tail-eq1} then becomes
\[
\ll \int_{\lambda = X^{-1/12}}^{c} \int_{s_1,s_2,s_3 = 1/2}^{\infty} 
\sum_{
    \substack{
    (A,B) \in S_Z(\mathcal{Y})\\
    a_{11} \neq 0\\
    |\operatorname{Disc}(A,B)| < X
    }
} \Phi'(\lambda a(s)^{-1}(A,B))
s_1^{-2} s_2^{-6} s_3^{-6} \ d^{\times }s \ d^{\times} \lambda,
\]
where $\Phi'$ denotes the characteristic function for $H'$. We recall that $\lambda  a(s)^{-1}(A,B) \in H'$ only if $(A,B) \in B_0$, where $B_0$ is the box defined in Equation 10 of \cite{MR2183288}. Thus, we have 
\begin{align*}
    \operatorname{\mathcal{N}}(S_Z(\mathcal{Y})\cap \{a_{11}\neq 0\}, X)
& \\ \ll \int_{\lambda = X^{-1/12}}^{c} &\int_{s_1,s_2,s_3 = 1/2}^{\infty} 
 \sum_{
    \substack{
    (A,B) \in S_Z(\mathcal{Y})\\
    a_{11} \neq 0\\
    |\operatorname{Disc}(A,B)| < X
    }
} \Phi_0(A,B)
s_1^{-2} s_2^{-6} s_3^{-6} \ d^{\times }s \ d^{\times} \lambda,
\end{align*}
\[ 
\]
where $\Phi_0$ is the characteristic function for $B_0$. Each side length of $B_0$ can be written in the form $r_i' \cdot \frac{120}{\lambda}$, and so we can invoke Theorem 13 of~\cite{BCT} to bound the integrand with $n = 12$, $k = 2$, $r_i = r_i'/\lambda$, and $B$ a centrally symmetric hypercube of side length $120$. We note that the product of the $r_i'$ is equal to 1, so $T = \lambda^{-12}$, which gives  
\[
\sum_{
    \substack{
    (A,B) \in S_Z(\mathcal{Y})\\
    a_{11} \neq 0\\
    |\operatorname{Disc}(A,B)| < X
    }
} \Phi_0(A,B)
\ll
\lambda^{-12 - \epsilon}
\left(
\frac{1}{r_1} + \frac{1}{Z}
\right)
\ll 
\lambda^{-12 - \epsilon}
\left(
\lambda s_1 s_2^4 s_3^2 + \frac{1}{Z}
\right).
\]
Here we have used $r_i' \gg s_1^{-1}s_2^{-4} s_3^{-2}$, which follows from the inequalities defining $B_0$ and the fact that the $s_i$ are absolutely bounded from below. Plugging this back into the integral gives
\[
\operatorname{\mathcal{N}}(S_Z(\mathcal{Y}) \cap \{a_{11} \neq 0\}, X) \ll 
X^{11/12 + \epsilon}
+
\frac{X}{Z^{1-\epsilon}}.
\]
Thus $\operatorname{\mathcal{N}}(S_Z(\mathcal{Y}), X) \ll X^{11/12 + \epsilon}
+
X/Z^{1-\varepsilon},
$

as desired.

As in Lemma~\ref{lemma: vp(N)} we write $\operatorname{N}(\Delta_{L/K})=N_0 N_1 N_2$
with $N_1$ being a $4$-th power in $\mathbb{Z}$.

Moreover we write $\Delta_K=3^a N_0 N_0'$ with $(N_0',3)=1$;

if $p\mid N_0'$, then  $p^2\mid\Delta_K$ by the proof of Lemma~\ref{lemma: vp(N)}. 
As we only seek an upper bound,
we will use the fact that $\operatorname{N}(\Delta_{L/K})\leq X$ implies
$N_0 N_1\leq X$ to avoid the wildly ramified primes in our count.
Let $Y>0$ be a parameter to be determined later.
We will condition on the value of $\operatorname{rad}(N_0')$.  

First, we treat the case where $\operatorname{rad}(N_0')\leq Y$.
Observe that $\Delta_K^2 N_0 N_1\leq |\Delta_L|\leq X$
and $N_0=\Delta_K/(3^a N_0')$
implies $N_1\leq 3^a N_0' X/\Delta_K^3$.
Moreover, in this case 

$N_0'\leq Y^2$
(by Lemma~\ref{lemma: vp(N)}, Part 3)
and hence $N_1\leq 3^a XY^2/\Delta_K^3$.
Making use of Lemma~\ref{L:fourth}, we estimate:
\begin{align*}
\sum_{|\Delta_K|\leq \sqrt{X}}
\sum_{\substack{N_0 N_1\leq X/\Delta_K^2\\ \operatorname{rad}(N_0')\leq Y}}
1
&\leq
\sum_{|\Delta_K|\leq \sqrt{X}}
\sum_{\substack{N_1\leq\frac{3^a XY^2}{\Delta_K^3}}}
1
\\
&\ll
\sum_{|\Delta_K|\leq \sqrt{X}}
|\Delta_K|^{\kappa+\varepsilon}\left(\frac{XY^2}{|\Delta_K|^3}\right)^{1/4}
\\[1ex]
&=
X^{1/4}Y^{1/2}\sum_{|\Delta_K|\leq \sqrt{X}}
|\Delta_K|^{\kappa-3/4+\varepsilon}
\\[1ex]
&\ll
X^{3/8+\kappa/2+\varepsilon}Y^{1/2}
\,.
\end{align*}

Now we treat the cases $\operatorname{rad}(N_0')>Y$.  In this case there exists a squarefree $q>Y$
such that $q^2\mid\Delta_K$; namely, $q=\operatorname{rad}(N_0')$.
This makes Lemma~\ref{L:tail} applicable,
which takes the form $O(X^{1-\delta+\varepsilon}+X/Y^{1-\varepsilon})$
with $\delta=1/12$.
We estimate:
\begin{align*}
\sum_{|\Delta_K|\leq \sqrt{X}}
\sum_{\substack{N_0 N_1\leq X/\Delta_K^2\\ \operatorname{rad}(N_0')>Y}}
1
&\leq
\sum_{\substack{|\Delta_K|\leq \sqrt{X}\\\exists q>Y\,q^2\mid\Delta_K}}
\sum_{\substack{N_1\leq X /\Delta_K^2\\ }}
1
\\
&\ll
\sum_{\substack{|\Delta_K|\leq \sqrt{X} \\\exists q>Y\,q^2\mid\Delta_K}}
|\Delta_K|^{\kappa+\varepsilon}\left(\frac{X}{\Delta_K^2}\right)^{1/4}
\\[1ex]
&=
X^{1/4}
\sum_{\substack{|\Delta_K|\leq \sqrt{X}\\\exists q>Y\,q^2\mid\Delta_K}}
|\Delta_K|^{\kappa-1/2+\varepsilon}
\\[1ex]
&\ll
X^{1/2+\kappa/2-\delta/2+\varepsilon}+X^{1/2+\kappa/2 + \varepsilon}Y^{-1}
\,.
\end{align*}

Summarizing, we have a bound of 
\begin{align*}
&\ll 
X^{3/8+\kappa/2}Y^{1/2}
+
X^{1/2+\kappa/2-\delta/2+\varepsilon}+X^{1/2+\kappa/2 + \epsilon}Y^{-1}
\\
&\ll
X^{5/12+\kappa/2+\varepsilon}+X^{1/2+\kappa/2-\delta/2+\varepsilon}
\,,
\end{align*}
where we have chosen $Y=X^{1/12}$.
Using the values of $\delta$ and $\kappa$ we have available to us,
we are forced to accept the second error term
which has exponent less than $0.598$.

\label{v_p(D1)}
    Let $G = Q_8 \rtimes S_4$. Write $\Delta_K=D_0 D_1 D_2$ with 
    \[
    (6,D_0)=1, \;\;
    \operatorname{rad}(D_0)\mid \operatorname{N}(\Delta_{L/K}), \;\;
    (D_1, 6 \operatorname{N}(\Delta_{L/K}))=1, \;\;
    D_2\mid 6^m.
    \]
    Then we have
    \begin{enumerate}
        \item $D_0^{1/3} \leq N_0 \leq D_0^3$,

        \item $D_1 = \operatorname{rad}(D_1)^2$.
    \end{enumerate}

We follow the proof for $\operatorname{GL}_2(\mathbb{F}_3)$ but some details are different. We note that in the subsequent calculations, we use the following analog of Lemma~\ref{L:fourth}, which is proved in the exact same way, except where $v_p(N_1) = 4$ is replaced by $v_p(N_1) \geq 2$:
\[
\sum_{
\substack{
    [L:K] = 2\\
    \operatorname{Gal}(\widetilde{L}/\mathbb{Q}) \cong G\\
    N_1 \leq Y\\
}
}{1}
\ll |\Delta_K|^{\kappa + \epsilon}Y^{1/2}.
\]
We write $\operatorname{N}(\Delta_{L/K})=N_0 N_1 N_2$
where these quantities are defined the same way as in Section~\ref{S:GL2F3}.
The analog of Lemma~\ref{lemma: vp(N)} is not totally true.
We have $v_p(N_1)\geq 2$ for all $p\mid N_1$, which is slightly weaker than Part 1 of the Lemma.

We condition on the value of $\operatorname{rad}(D_1)$.

First, we consider the case where $\operatorname{rad}(D_1)\leq Y$.
Notice that the condition $|\Delta_L|\leq X$ implies $N_1\leq X/(\Delta_K^2 N_0)$.
Further, this implies
$$
  N_1\leq \frac{X}{\Delta_K^2 D_0^{1/3}}\leq\frac{2^a 3^bXY^{2/3}}{\Delta_K^{2+1/3}}
  \,.
$$
Indeed, observe that $|\Delta_K|=D_0 D_1 D_2\leq 2^a 3^b D_0 Y^2$,
which implies $D_0\geq \Delta_K/(2^a 3^bY^2)$. 

We estimate: 
\begin{align*}
\sum_{
\substack{
|\Delta_K|\leq \sqrt{X}\\
\operatorname{rad}(D_1) \leq Y\\
}
}
\sum_{
\substack{
N_0 N_1\leq X/\Delta_K^2
}
}
1
&\leq
\sum_{|\Delta_K|\leq \sqrt{X}}
\sum_{\substack{N_1\leq\frac{2^a 3^bXY^{2/3}}{\Delta_K^{2+1/3}}}}
1
\\
&\ll
\sum_{|\Delta_K|\leq \sqrt{X}}
|\Delta_K|^{\kappa + \varepsilon}
\left( 
\frac{XY^{2/3}}{\Delta_K^{2 + 1/3}}
\right)^{1/2}
\\
&
=
X^{1/2}Y^{1/3}
\sum_{|\Delta_K|\leq \sqrt{X}}
|\Delta_K|^{\kappa - 7/6 + \varepsilon}
\\
&\ll X^{1/2+\kappa/2-1/12+\varepsilon}Y^{1/3}.
\end{align*}
In the case where $\operatorname{rad}(N_0')>Y$, we have
\begin{align*}
    \sum_{
\substack{
|\Delta_K|\leq \sqrt{X}\\
\operatorname{rad}(D_1) > Y\\
}
}
\sum_{
\substack{
N_0 N_1\leq X/\Delta_K^2
}
}
1
&\leq
\sum_{
\substack{|\Delta_K|\leq \sqrt{X}\\\exists q>Y\,q^2\mid\Delta_K}
}
\sum_{\substack{N_1\leq X/\Delta_K^2\\ }}
1
\\
&\ll
\sum_{
\substack{|\Delta_K|\leq \sqrt{X}\\ \exists q>Y\,q^2\mid\Delta_K}
}
|\Delta_K|^{\kappa + \varepsilon}
\left(
\frac{X}{\Delta_K^2}
\right)^{1/2}
\\[1ex]
&=
X^{1/2}
\sum_{\substack{|\Delta_K|\leq \sqrt{X}\\\exists q>Y\,q^2\mid\Delta_K}}
|\Delta_K|^{\kappa-1+\varepsilon}
\\ &
\ll X^{1/2+\kappa/2-\delta/2+\varepsilon}+X^{1/2+\kappa/2+\varepsilon}Y^{-1}.
\end{align*}
Then we choose $Y=X^{1/16}$ and the final estimate is
\[
\ll X^{1/2+\kappa/2-1/16}+X^{1/2+\kappa/2-\delta/2+\varepsilon}.
\]
As before, we are forced to accept the second error term due to the values of $\delta$, $\kappa$ that we
have available.
